  9	import {
 10	  getPlatformKey,
 11	  getPlatformInfo,
 12	  readManifest,
 13	  readInstalled,
 14	  writeInstalled,
 15	  extractBundledCLI,
 16	  downloadAndInstallCLI,
 17	  downloadAndInstallUV,
 18	  copyUVWrapper,
