 22	const execAsync = promisify(execFile);
 23	
 24	const MIN_CLI_VERSION = "0.82";
 25	const MIN_WIRE_VERSION = "1.1";
 26	
 27	let instance: CLIManager;
 28	
 29	function errorText(err: unknown): string {
 30	  const stderr = textFromErrorField(err, "stderr");
 31	  const stdout = textFromErrorField(err, "stdout");
 32	  const message = err instanceof Error ? err.message : String(err);
 33	  return stderr || stdout || message;
 34	}
 35	
 36	function textFromErrorField(err: unknown, field: "stdout" | "stderr"): string {
 37	  const value = (err as { stdout?: unknown; stderr?: unknown } | null)?.[field];
 38	  if (!value) {
 39	    return "";
 40	  }
 41	  return Buffer.isBuffer(value) ? value.toString().trim() : String(value).trim();
 42	}
