 44	export const initCLIManager = (ctx: vscode.ExtensionContext) => (instance = new CLIManager(ctx));
 45	export const getCLIManager = () => {
 46	  if (!instance) {
 47	    throw new Error("CLI not init");
 48	  }
 49	  return instance;
 50	};
