  5	interface ActiveToken {
  6	  trigger: "/" | "@";
  7	  start: number;
  8	  query: string;
  9	}
 10	
 11	function fuzzyMatch(text: string, query: string): boolean {
 12	  if (!query) {
 13	    return true;
 14	  }
 15	  const lowerText = text.toLowerCase();
 16	  const lowerQuery = query.toLowerCase();
 17	  let qi = 0;
 18	  for (let i = 0; i < lowerText.length && qi < lowerQuery.length; i++) {
 19	    if (lowerText[i] === lowerQuery[qi]) {
 20	      qi++;
 21	    }
 22	  }
 23	  return qi === lowerQuery.length;
 24	}
 25	
 26	export function findActiveToken(text: string, cursorPos: number): ActiveToken | null {
 27	  const beforeCursor = text.slice(0, cursorPos);
 28	  const lastSpace = Math.max(beforeCursor.lastIndexOf(" "), beforeCursor.lastIndexOf("\n"), beforeCursor.lastIndexOf("\t"), -1);
 29	  const currentWord = beforeCursor.slice(lastSpace + 1);
 30	
 31	  if (currentWord.startsWith("@")) {
 32	    return { trigger: "@", start: lastSpace + 1, query: currentWord.slice(1) };
 33	  }
 34	  if (currentWord.startsWith("/")) {
 35	    return { trigger: "/", start: lastSpace + 1, query: currentWord.slice(1) };
 36	  }
 37	  return null;
 38	}
