 40	interface UseSlashMenuResult {
 41	  showSlashMenu: boolean;
 42	  filteredCommands: SlashCommandInfo[];
 43	  selectedIndex: number;
 44	  setSelectedIndex: (index: number) => void;
 45	  handleSlashMenuKey: (e: React.KeyboardEvent) => boolean;
 46	  resetSlashMenu: () => void;
 47	}
 48	
 49	export function useSlashMenu(activeToken: ActiveToken | null, onSelectCommand: (name: string) => void, onCancel: () => void): UseSlashMenuResult {
 50	  const [selectedIndex, setSelectedIndex] = useState(0);
 51	  const { slashCommands } = useSettingsStore();
 52	
 53	  const showSlashMenu = activeToken?.trigger === "/";
 54	
 55	  const filteredCommands = useMemo(() => {
 56	    if (!showSlashMenu) {
 57	      return [];
 58	    }
 59	    const q = activeToken.query;
 60	    if (!q) {
 61	      return slashCommands;
 62	    }
 63	    return slashCommands.filter((cmd) => fuzzyMatch(cmd.name, q) || fuzzyMatch(cmd.description, q));
 64	  }, [showSlashMenu, activeToken?.query, slashCommands]);
 65	
 66	  const resetSlashMenu = useCallback(() => {
 67	    setSelectedIndex(0);
 68	  }, []);
 69	
 70	  const handleSlashMenuKey = useCallback(
 71	    (e: React.KeyboardEvent): boolean => {
 72	      if (!showSlashMenu || filteredCommands.length === 0) {
 73	        return false;
 74	      }
 75	
 76	      switch (e.key) {
 77	        case "ArrowDown":
 78	          e.preventDefault();
 79	          setSelectedIndex((i) => Math.min(i + 1, filteredCommands.length - 1));
 80	          return true;
 81	        case "ArrowUp":
 82	          e.preventDefault();
 83	          setSelectedIndex((i) => Math.max(i - 1, 0));
 84	          return true;
 85	        case "Tab":
 86	        case "Enter": {
 87	          e.preventDefault();
 88	          const cmd = filteredCommands[selectedIndex];
 89	          if (cmd) {
 90	            onSelectCommand(cmd.name);
 91	          }
 92	          return true;
 93	        }
 94	        case "Escape":
 95	          e.preventDefault();
 96	          onCancel();
 97	          return true;
 98	        default:
 99	          return false;
100	      }
101	    },
102	    [showSlashMenu, filteredCommands, selectedIndex, onSelectCommand, onCancel],
103	  );
104	
105	  return {
106	    showSlashMenu,
107	    filteredCommands,
108	    selectedIndex,
109	    setSelectedIndex,
110	    handleSlashMenuKey,
111	    resetSlashMenu,
112	  };
113	}

