409	/** One-time run: create session, send message, collect all events, and automatically close session after returning result */
410	export async function prompt(content: string | ContentPart[], options: Omit<SessionOptions, "sessionId">): Promise<{ result: RunResult; events: StreamEvent[] }> {
411	  const session = createSession(options);
412	  try {
413	    const turn = session.prompt(content);
414	    const events: StreamEvent[] = [];
415	    for await (const event of turn) {
416	      events.push(event);
417	    }
418	    return { result: await turn.result, events };
419	  } finally {
420	    await session.close();
421	  }
422	}

