141	// Raw DisplayBlock parsing schema
142	const RawDisplayBlockSchema = z
143	  .object({
144	    type: z.string(),
145	    text: z.string().optional(),
146	    path: z.string().optional(),
147	    old_text: z.string().optional(),
148	    new_text: z.string().optional(),
