155	// DisplayBlock schema with automatic strong typing
156	export const DisplayBlockSchema = RawDisplayBlockSchema.transform((raw): DisplayBlock => {
157	  switch (raw.type) {
158	    case "brief":
159	      if (typeof raw.text === "string") {
160	        return { type: "brief", text: raw.text };
161	      }
162	      break;
163	    case "diff":
164	      if (typeof raw.path === "string" && typeof raw.old_text === "string" && typeof raw.new_text === "string") {
165	        return { type: "diff", path: raw.path, old_text: raw.old_text, new_text: raw.new_text };
166	      }
167	      break;
168	    case "todo":
169	      if (Array.isArray(raw.items)) {
170	        return { type: "todo", items: raw.items };
171	      }
172	      break;
173	    case "shell":
174	      if (typeof raw.language === "string" && typeof raw.command === "string") {
175	        return { type: "shell", language: raw.language, command: raw.command };
176	      }
177	      break;
178	  }
179	  const { type, ...rest } = raw;
180	  return { type, data: rest };
181	});
