529	/**
530	 * Wire event union type
531	 * Sent from Agent to Client via `event` method, no response required
532	 */
533	export type WireEvent =
534	  | { type: "TurnBegin"; payload: TurnBegin }
535	  | { type: "TurnEnd"; payload: TurnEnd }
536	  | { type: "StepBegin"; payload: StepBegin }
537	  | { type: "StepInterrupted"; payload: StepInterrupted }
538	  | { type: "CompactionBegin"; payload: CompactionBegin }
539	  | { type: "CompactionEnd"; payload: CompactionEnd }
540	  | { type: "StatusUpdate"; payload: StatusUpdate }
541	  | { type: "HookTriggered"; payload: HookTriggered }
542	  | { type: "HookResolved"; payload: HookResolved }
543	  | { type: "ContentPart"; payload: ContentPart }
544	  | { type: "ToolCall"; payload: ToolCall }
545	  | { type: "ToolCallPart"; payload: ToolCallPart }
546	  | { type: "ToolResult"; payload: ToolResult }
547	  | { type: "SteerInput"; payload: SteerInput }
548	  | { type: "SubagentEvent"; payload: SubagentEvent }
549	  | { type: "ApprovalResponse"; payload: ApprovalResponseEvent }
550	  | { type: "ParseError"; payload: ParseErrorPayload };
