552	export type WireRequest =
553	  | { type: "ApprovalRequest"; payload: ApprovalRequestPayload }
554	  | { type: "ToolCallRequest"; payload: ToolCallRequest }
555	  | { type: "QuestionRequest"; payload: QuestionRequest }
556	  | { type: "HookRequest"; payload: HookRequest };
