559	export const EventSchemas: Record<string, z.ZodSchema> = {
560	  TurnBegin: TurnBeginSchema,
561	  TurnEnd: EmptyPayloadSchema,
562	  StepBegin: StepBeginSchema,
563	  StepInterrupted: EmptyPayloadSchema,
564	  CompactionBegin: EmptyPayloadSchema,
565	  CompactionEnd: EmptyPayloadSchema,
566	  StatusUpdate: StatusUpdateSchema,
567	  HookTriggered: HookTriggeredSchema,
568	  HookResolved: HookResolvedSchema,
569	  ContentPart: ContentPartSchema,
570	  ToolCall: ToolCallSchema,
571	  ToolCallPart: ToolCallPartSchema,
572	  ToolResult: ToolResultSchema,
573	  ApprovalResponse: ApprovalResponseEventSchema,
574	  SteerInput: SteerInputSchema,
