577	// Request type -> schema mapping
578	export const RequestSchemas: Record<string, z.ZodSchema> = {
579	  ApprovalRequest: ApprovalRequestPayloadSchema,
580	  ToolCallRequest: ToolCallRequestSchema,
581	  QuestionRequest: QuestionRequestSchema,
582	  HookRequest: HookRequestSchema,
583	};
