585	type Result<T> = { ok: true; value: T } | { ok: false; error: string };
586	
587	// Parse wire event (internal use)
588	export function parseEventPayload(type: string, payload: unknown): Result<WireEvent> {
589	  const schema = EventSchemas[type];
590	  if (!schema) {
591	    return { ok: false, error: `Unknown event type: ${type}` };
592	  }
593	  const result = schema.safeParse(payload);
594	  if (!result.success) {
595	    return { ok: false, error: `Invalid payload for ${type}: ${result.error.message}` };
596	  }
597	  return { ok: true, value: { type, payload: result.data } as WireEvent };
598	}
