600	function parseWireEvent(raw: { type: string; payload?: unknown }): WireEvent {
601	  const result = parseEventPayload(raw.type, raw.payload);
602	  if (result.ok) {
603	    return result.value;
604	  }
605	  return {
606	    type: "ParseError",
607	    payload: {
608	      code: "SUBAGENT_PARSE_FAILED",
609	      message: result.error,
610	      rawType: raw.type,
611	    },
612	  };
613	}
