704	export function parseRequestPayload(type: string, payload: unknown): Result<WireRequest> {
705	  const schema = RequestSchemas[type];
706	  if (!schema) {
707	    return { ok: false, error: `Unknown request type: ${type}` };
708	  }
709	  const result = schema.safeParse(payload);
710	  if (!result.success) {
711	    return { ok: false, error: `Invalid payload for ${type}: ${result.error.message}` };
712	  }
713	  return { ok: true, value: { type, payload: result.data } as WireRequest };
714	}
