 21	function extractDiffPaths(display?: { type: string; path?: string }[]): string[] {
 22	  if (!display) {
 23	    return [];
 24	  }
 25	  return display.filter((block): block is DiffBlock => block.type === "diff" && typeof block.path === "string").map((block) => block.path);
 26	}
