 33	function hasContent(message: ChatMessage): boolean {
 34	  if (typeof message.content === "string" && message.content.trim()) {
 35	    return true;
 36	  }
 37	  if (Array.isArray(message.content) && message.content.length > 0) {
 38	    return true;
 39	  }
 40	
 41	  return message.steps?.some((s) => s.items.length > 0) ?? false;
 42	}
