 65	const CANCELLED_RESULT: ToolReturnValue = {
 66	  is_error: false,
 67	  output: "Cancelled by user",
 68	  message: "Cancelled by user",
 69	  display: [],
 70	};
 71	
 72	function markPendingToolsAsCancelled(steps: UIStep[]): void {
 73	  for (const step of steps) {
 74	    for (const item of step.items) {
 75	      if (item.type === "tool_use" && item.result === undefined) {
 76	        item.result = CANCELLED_RESULT;
 77	      }
 78	      if (item.type === "tool_use" && item.subagent_steps) {
 79	        markPendingToolsAsCancelled(item.subagent_steps);
 80	      }
 81	    }
 82	  }
 83	}
 84	
 85	function resolveSubagentTarget(
 86	  steps: UIStep[],
 87	  payload: SubagentEvent,
 88	): { steps: UIStep[]; event: { type: string; payload: any }; toolItem: UIStepItem & { type: "tool_use" } } | null {
 89	  const { parent_tool_call_id, event } = payload;
 90	
 91	  // Nested SubagentEvent
 92	  if (event.type === "SubagentEvent") {
 93	    return resolveSubagentTarget(steps, event.payload as SubagentEvent);
 94	  }
 95	
 96	  const toolItem = findToolUseItem(steps, parent_tool_call_id);
 97	  if (!toolItem) {
 98	    return null;
 99	  }
100	
101	  if (!toolItem.subagent_steps) {
102	    toolItem.subagent_steps = [];
103	  }
104	
105	  return { steps: toolItem.subagent_steps, event, toolItem };
106	}
107	
108	function finishAllTextItems(steps: UIStep[]): void {
109	  for (const step of steps) {
110	    for (const item of step.items) {
111	      if (item.type === "text" || item.type === "thinking") {
112	        item.finished = true;
113	      }
114	      if (item.type === "tool_use" && item.subagent_steps) {
115	        finishAllTextItems(item.subagent_steps);
116	      }
117	    }
118	  }
119	}
120	
121	function applyEventToSteps(steps: UIStep[], event: { type: string; payload: any }, onText?: (text: string) => void): void {
122	  const ensureCurrentStep = (): UIStep => {
123	    let step = steps.at(-1);
124	    if (!step) {
125	      step = { n: 1, items: [] };
126	      steps.push(step);
127	    }
128	    return step;
129	  };
130	
131	  const appendOrCreate = (type: "text" | "thinking", content: string): void => {
132	    const currentStep = ensureCurrentStep();
133	    const last = currentStep.items.at(-1);
134	
135	    if (last?.type === type) {
136	      (last as { content: string }).content += content;
137	    } else {
138	      currentStep.items.push({ type, content });
139	    }
140	  };
141	
142	  const findLastToolUse = (): (UIStepItem & { type: "tool_use" }) | null => {
143	    for (let i = steps.length - 1; i >= 0; i--) {
144	      const items = steps[i].items;
145	
146	      for (let j = items.length - 1; j >= 0; j--) {
147	        if (items[j].type === "tool_use") {
148	          return items[j] as UIStepItem & { type: "tool_use" };
149	        }
150	      }
151	    }
152	
153	    return null;
154	  };
155	
156	  const updateToolResult = (toolCallId: string, returnValue: ToolResult["return_value"]): boolean => {
157	    for (const step of steps) {
158	      for (const item of step.items) {
159	        if (item.type === "tool_use") {
160	          if (item.id === toolCallId) {
161	            item.result = returnValue;
162	            return true;
163	          }
164	
165	          if (item.subagent_steps && applyToolResult(item.subagent_steps, toolCallId, returnValue)) {
166	            return true;
167	          }
168	        }
169	      }
170	    }
171	
172	    return false;
173	  };
174	
175	  const applyToolResult = (subSteps: UIStep[], toolCallId: string, returnValue: ToolResult["return_value"]): boolean => {
176	    for (const step of subSteps) {
177	      for (const item of step.items) {
178	        if (item.type === "tool_use") {
179	          if (item.id === toolCallId) {
180	            item.result = returnValue;
181	            return true;
182	          }
183	
184	          if (item.subagent_steps && applyToolResult(item.subagent_steps, toolCallId, returnValue)) {
185	            return true;
186	          }
187	        }
188	      }
189	    }
190	
191	    return false;
192	  };
193	
194	  switch (event.type) {
195	    case "StepBegin":
196	      finishAllTextItems(steps);
197	      steps.push({ n: event.payload.n, items: [] });
198	      break;
199	
200	    case "ContentPart": {
201	      const part = event.payload as ContentPart;
202	
203	      if (part.type === "text" && part.text) {
204	        appendOrCreate("text", part.text);
205	        onText?.(part.text);
206	      } else if (part.type === "think" && part.think) {
207	        appendOrCreate("thinking", part.think);
208	      }
209	
210	      break;
211	    }
212	
213	    case "ToolCall": {
214	      finishAllTextItems(steps);
215	      const call = event.payload as ToolCall;
216	      const currentStep = ensureCurrentStep();
217	
218	      currentStep.items.push({
219	        type: "tool_use",
220	        id: call.id,
221	        call: {
222	          id: call.id,
223	          name: call.function.name,
224	          arguments: call.function.arguments ?? null,
225	        },
226	      });
227	
228	      break;
229	    }
230	
231	    case "ToolCallPart": {
232	      const { arguments_part } = event.payload;
233	      if (!arguments_part) {
234	        break;
235	      }
236	      const tool = findLastToolUse();
237	
238	      if (tool) {
239	        tool.call.arguments = (tool.call.arguments || "") + arguments_part;
240	      }
241	
242	      break;
243	    }
244	
245	    case "ToolResult": {
246	      const result = event.payload as ToolResult;
247	      updateToolResult(result.tool_call_id, result.return_value);
248	
249	      const paths = extractDiffPaths(result.return_value.display);
250	      if (paths.length > 0) {
251	        bridge.trackFiles(paths);
252	      }
253	
254	      break;
255	    }
256	  }
257	}
