260	  if (!steps) {
261	    return false;
262	  }
263	  const toolItem = findToolUseItem(steps, toolCallId);
264	  return toolItem?.call.name === "Task" || toolItem?.call.name === "Agent" || toolItem?.call.name === "spawn_subagent";
265	}
