291	function handleRuntimeError(draft: ChatState, code: string, message: string, detail?: string): void {
292	  // Runtime: 保留现场，添加内嵌错误
293	  addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
294	  draft.activeTokenUsage = createEmptyTokenUsage();
295	  draft.isStreaming = false;
296	  draft.isCompacting = false;
297	  useApprovalStore.getState().clearRequests();
298	
299	  const lastAssistant = getLastAssistant(draft);
300	  if (lastAssistant) {
301	    // 如果完全没有内容，添加一个空的 step 以便显示错误
302	    if (!lastAssistant.steps) {
303	      lastAssistant.steps = [];
304	    }
305	    finishAllTextItems(lastAssistant.steps);
306	    // 设置内嵌错误，保留服务器原始错误信息
307	    lastAssistant.inlineError = { code, message, detail };
308	  }
309	}
