598	export function processEvent(draft: ChatState, event: UIStreamEvent): void {
599	  const handler = eventHandlers[event.type];
600	
601	  if (handler) {
602	    const payload = "payload" in event ? event.payload : event;
603	    handler(draft, payload);
604	  }
605	}

