395	  processEvent: (event) => {
396	    // Clear handshake timeout on receiving valid response
397	    if (event.type === "TurnBegin" || event.type === "StepBegin" || event.type === "ContentPart") {
398	      clearHandshakeTimer();
399	      set({ handshakeReceived: true });
400	    }
401	
402	    set(
403	      produce((draft: ChatState) => {
404	        // Route event to correct tab by explicit mode, then sessionId, then active tab fallback
405	        const targetTab = getTargetTab(event as any, {
406	          activeTab: draft.activeTab,
407	          thinkSessionId: draft.think.sessionId,
408	          doSessionId: draft.do.sessionId,
409	        });
410	        const activeTab = draft.activeTab;
411	
412	        // If the event targets the inactive tab, swap its state into the flat
413	        // scratch space so legacy handlers (which mutate flat state) operate on
414	        // the right tab. Then swap back.
415	        if (targetTab !== activeTab) {
416	          syncTabStateFromFlat(draft, activeTab);
417	          syncFlatStateFromTab(draft, targetTab);
418	        }
419	
420	        processEvent(draft, event);
421	
422	        syncTabStateFromFlat(draft, targetTab);
423	
424	        if (targetTab !== activeTab) {
425	          syncFlatStateFromTab(draft, activeTab);
426	        }
427	
428	        // Invariant: flat state must always reflect the active tab
429	        if (draft.messages !== draft[draft.activeTab].messages) {
430	          console.warn(
431	            `[chat.store invariant] messages mismatch: flat state points to ${draft.messages === draft.think.messages ? 'think' : draft.messages === draft.do.messages ? 'do' : 'unknown'}, activeTab=${draft.activeTab}`,
432	          );
433	        }
434	        if (draft.isStreaming !== draft[draft.activeTab].isStreaming) {
435	          console.warn(
436	            `[chat.store invariant] isStreaming mismatch: flat=${draft.isStreaming}, ${draft.activeTab}.isStreaming=${draft[draft.activeTab].isStreaming}`,
437	          );
438	        }
439	        if (draft.think.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.do.sessionId)) {
440	          console.warn(`[chat.store invariant] Think tab contains messages from Do session ${draft.do.sessionId}`);
441	        }
442	        if (draft.do.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.think.sessionId)) {
443	          console.warn(`[chat.store invariant] Do tab contains messages from Think session ${draft.think.sessionId}`);
444	        }
445	      }),
446	    );
447	
448	    // Auto-send next queued item when streaming ends (complete, abort, or error).
449	    // history_restored does NOT trigger auto-send — the user is reviewing history.
450	    if (event.type === "stream_complete" || event.type === "stream_aborted" || event.type === "error") {
451	      const { queue, isStreaming: stillStreaming } = get();
452	      if (!stillStreaming && queue.length > 0) {
453	        setTimeout(() => get().sendNextQueued(), 50);
454	      }
455	    }
456	  },
