 27	  constructor() {
 28	    this.webviewId = document.body.getAttribute("data-webviewid") || `unknown_${Date.now()}`;
 29	
 30	    if (typeof acquireVsCodeApi === "function") {
 31	      this.vscode = acquireVsCodeApi();
 32	    } else {
 33	      console.warn("[Consilium Bridge] Running outside VS Code, using mock");
 34	      this.vscode = {
 35	        postMessage: (msg) => console.log("[Consilium Mock]", msg),
 36	        getState: () => undefined,
