 44	  private handleMessage = (event: MessageEvent) => {
 45	    const processMsg = (msg: any) => {
 46	      if (msg.id && this.pending.has(msg.id)) {
 47	        const { resolve, reject, timeout } = this.pending.get(msg.id)!;
 48	        clearTimeout(timeout);
 49	        this.pending.delete(msg.id);
 50	
 51	        if (msg.error) {
 52	          reject(new Error(msg.error));
 53	        } else {
 54	          resolve(msg.result);
 55	        }
 56	        return;
 57	      }
 58	
 59	      if (msg.event) {
 60	        const handlers = this.eventHandlers.get(msg.event);
 61	        handlers?.forEach((h) => h(msg.data));
 62	      }
 63	    };
 64	
 65	    if (Array.isArray(event.data)) {
 66	      event.data.forEach(processMsg);
 67	    } else {
 68	      processMsg(event.data);
 69	    }
 70	  };
