 89	    }
 90	    this.eventHandlers.get(event)!.add(handler as (data: unknown) => void);
 91	
 92	    return () => {
 93	      this.eventHandlers.get(event)?.delete(handler as (data: unknown) => void);
 94	    };
 95	  }
