 47	function buildSystemContext(sessionId: string): string {
 48	  const mode = VSCodeSettings.editorContext;
 49	  if (mode === "never") {
 50	    return "";
 51	  }
 52	
 53	  const editor = vscode.window.activeTextEditor;
 54	  if (!editor) {
 55	    return "";
 56	  }
 57	
 58	  const doc = editor.document;
 59	  const relativePath = vscode.workspace.asRelativePath(doc.uri);
 60	  const lastPath = injectedEditorContextSessions.get(sessionId);
 61	
 62	  if (mode === "onConversationStart") {
 63	    // Already injected once, skip
 64	    if (lastPath !== undefined) {
 65	      return "";
 66	    }
 67	  } else {
 68	    // onFileChange: skip if same file
 69	    if (lastPath === relativePath) {
 70	      return "";
 71	    }
 72	  }
 73	
 74	  injectedEditorContextSessions.set(sessionId, relativePath);
 75	
 76	  const sel = editor.selection;
 77	
 78	  const selectionInfo = !sel.isEmpty ? ` (L${sel.start.line + 1}-${sel.end.line + 1} selected)` : "";
 79	  const unsavedInfo = doc.isDirty ? ", unsaved" : "";
 80	
 81	  return `<system>Editor context (use only if relevant to user's query): ${relativePath}:${sel.active.line + 1}${selectionInfo}${unsavedInfo}.</system>\n`;
 82	}
 83	
 84	function prependSystemContext(content: string | ContentPart[], ctx: string): string | ContentPart[] {
 85	  if (!ctx) {
 86	    return content;
 87	  }
 88	
 89	  if (typeof content === "string") {
 90	    return content + "\n" + ctx;
 91	  }
 92	
 93	  const idx = content.findIndex((p) => p.type === "text");
 94	  if (idx >= 0) {
 95	    const copy = [...content];
 96	    const part = copy[idx] as { type: "text"; text: string };
 97	    copy[idx] = { type: "text", text: ctx + part.text };
 98	    return copy;
 99	  }
100	
101	  return [{ type: "text", text: ctx }, ...content];
102	}
