104	function saveBaselineForPath(filePath: string, workDir: string, sessionId: string): boolean {
105	  const absolutePath = path.isAbsolute(filePath) ? filePath : path.join(workDir, filePath);
106	  const relativePath = path.relative(workDir, absolutePath);
107	
108	  if (relativePath.startsWith("..") || path.isAbsolute(relativePath)) {
109	    return false;
110	  }
111	
112	  let content = "";
113	  if (fs.existsSync(absolutePath)) {
114	    try {
115	      content = fs.readFileSync(absolutePath, "utf-8");
116	    } catch {
117	      // File unreadable, use empty baseline (for new files)
118	    }
119	  }
120	
121	  BaselineManager.saveBaseline(workDir, sessionId, relativePath, content);
122	  return true;
123	}
