125	function tryParseAndSaveBaseline(call: PendingToolCall, workDir: string, sessionId: string): boolean {
126	  if (call.baselineSaved || !FILE_TOOLS.has(call.name) || !call.arguments) {
127	    return false;
128	  }
129	
130	  try {
131	    const args = JSON.parse(call.arguments);
132	    if (args.path && saveBaselineForPath(args.path, workDir, sessionId)) {
133	      call.baselineSaved = true;
134	      return true;
135	    }
136	  } catch {
137	    // JSON not complete yet or invalid
138	  }
139	  return false;
140	}
