142	const streamChat: Handler<StreamChatParams, { done: boolean }> = async (params, ctx) => {
143	  if (!ctx.workDir) {
144	    ctx.broadcast(
145	      Events.StreamEvent,
146	      {
147	        type: "error",
148	        code: "NO_WORKSPACE",
149	        message: "Please open a folder to start.",
150	        phase: "preflight" as ErrorPhase,
151	      },
152	      ctx.webviewId,
153	    );
154	    vscode.window.showWarningMessage("Consilium: Please open a folder first.", "Open Folder").then((a) => {
155	      if (a) {
156	        vscode.commands.executeCommand("vscode.openFolder");
157	      }
158	    });
159	    return { done: false };
160	  }
161	
162	  if (VSCodeSettings.autosave) {
163	    await ctx.saveAllDirty();
164	  }
165	
166	  // Guard against continuing a session in the wrong tab. This prevents Do sessions
167	  // from being silently converted into Think sessions (and vice versa).
168	  const requestedMode = params.mode ?? 'think';
169	  if (params.sessionId) {
170	    const meta = ctx.getSessionMetadata(params.sessionId);
171	    if (meta && meta.mode && meta.mode !== 'legacy' && meta.mode !== requestedMode) {
172	      throw new Error(
173	        `Session ${params.sessionId} is a ${meta.mode} session. ` +
174	        `Switch to the ${meta.mode} tab before continuing.`
175	      );
176	    }
177	  }
178	
179	  const session = await ctx.getOrCreateSession(params.model, params.thinking, params.sessionId, params.mode);
180	  const workDir = ctx.workDir;
181	  const sessionId = session.sessionId;
182	  const mode = requestedMode;
183	
184	  // New session, set fallback title from first message
185	  if (!params.sessionId && typeof params.content === 'string') {
186	    const title = deriveTitleFromText(params.content);
187	    ctx.setSessionMetadata(sessionId, {
188	      mode: params.mode ?? 'think',
189	      title,
190	      titleSource: 'fallback',
191	    });
192	  } else if (!params.sessionId && Array.isArray(params.content)) {
193	    const title = deriveTitleFromText(extractTextFromContent(params.content));
194	    ctx.setSessionMetadata(sessionId, {
195	      mode: params.mode ?? 'think',
196	      title,
197	      titleSource: 'fallback',
198	    });
199	  } else if (params.sessionId) {
200	    // Session exists, update mode if it changed, but keep title
201	    const meta = ctx.getSessionMetadata(sessionId);
202	    const newMode = params.mode ?? 'think';
203	    if (!meta || meta.mode !== newMode) {
204	      ctx.setSessionMetadata(sessionId, {
205	        mode: newMode,
206	        title: meta?.title,
207	        titleSource: meta?.titleSource,
208	        titleGeneratedAt: meta?.titleGeneratedAt,
209	      });
210	    }
211	  }
212	
213	  // Track pending tool calls for baseline saving
214	  BaselineManager.initSession(workDir, sessionId);
215	
216	  ctx.broadcast(Events.StreamEvent, { type: "session_start", sessionId, model: session.model, _sessionId: sessionId, mode }, ctx.webviewId);
217	
218	  const systemContext = buildSystemContext(sessionId);
219	  const contentWithContext = prependSystemContext(params.content, systemContext);
220	
221	  const pendingToolCalls = new Map<string, PendingToolCall>();
222	  let lastToolCallId: string | null = null;
223	  const assistantTextChunks: string[] = [];
224	
225	  // Extract first user message text for potential title generation.
226	  const firstUserText = extractTextFromContent(params.content);
227	
228	  try {
229	    const turn = session.prompt(contentWithContext);
230	    ctx.setTurn(turn);
231	
232	    let result: RunResult = { status: "finished" };
233	
234	    for await (const event of turn) {
235	      const eventAny = event as any;
236	      const eventType = event.type;
237	      const payload = eventAny.payload;
238	
239	      // Accumulate assistant text for title generation.
240	      if (eventType === "ContentPart" && payload?.type === "text" && typeof payload.text === "string") {
241	        assistantTextChunks.push(payload.text);
242	      }
243	
244	      // ToolCall: Record and try to save baseline immediately if args are complete
245	      if (eventType === "ToolCall" && payload?.id) {
246	        const call: PendingToolCall = {
247	          id: payload.id,
248	          name: payload.function?.name || "",
249	          arguments: payload.function?.arguments || "",
250	          baselineSaved: false,
251	        };
252	        pendingToolCalls.set(payload.id, call);
253	        lastToolCallId = payload.id;
254	
255	        // Try to save baseline immediately (for YOLO / approve_for_session where args come complete)
256	        tryParseAndSaveBaseline(call, workDir, sessionId);
257	      }
258	
259	      // ToolCallPart: Accumulate arguments and try to save baseline
260	      if (eventType === "ToolCallPart" && payload?.arguments_part && lastToolCallId) {
261	        const call = pendingToolCalls.get(lastToolCallId);
262	        if (call) {
263	          call.arguments += payload.arguments_part;
264	          // Try to save after each part (will succeed when JSON becomes complete)
265	          tryParseAndSaveBaseline(call, workDir, sessionId);
266	        }
267	      }
268	
269	      // StatusUpdate: Last chance to save baseline before potential file modification
270	      if (eventType === "StatusUpdate") {
271	        for (const call of pendingToolCalls.values()) {
272	          tryParseAndSaveBaseline(call, workDir, sessionId);
273	        }
274	      }
275	
276	      // ToolResult: Clean up
277	      if (eventType === "ToolResult" && payload?.tool_call_id) {
278	        pendingToolCalls.delete(payload.tool_call_id);
279	        if (lastToolCallId === payload.tool_call_id) {
280	          lastToolCallId = null;
281	        }
282	      }
283	
284	      ctx.broadcast(Events.StreamEvent, { ...event, _sessionId: sessionId, mode }, ctx.webviewId);
285	    }
286	
287	    result = await turn.result;
288	
289	    ctx.broadcast(Events.StreamEvent, { type: "stream_complete", result, _sessionId: sessionId, mode }, ctx.webviewId);
290	    ctx.setTurn(null);
291	
292	    // After the first assistant turn, generate a meaningful title if none exists yet.
293	    const currentMeta = ctx.getSessionMetadata(sessionId);
294	    const hasUserTitle = currentMeta?.titleSource === "user";
295	    const hasLlmTitle = currentMeta?.titleSource === "llm";
296	    if (!hasUserTitle && !hasLlmTitle && firstUserText) {
297	      const firstAssistantText = assistantTextChunks.join("").trim();
298	      generateTitleForSession({
299	        firstUserText,
300	        firstAssistantText,
301	        model: params.model,
302	        mode: params.mode,
303	      }).then((generatedTitle) => {
304	        if (generatedTitle) {
305	          ctx.setSessionMetadata(sessionId, {
306	            mode: params.mode ?? currentMeta?.mode ?? "think",
307	            title: generatedTitle,
308	            titleSource: "llm",
309	            titleGeneratedAt: Date.now(),
310	          });
311	          ctx.broadcast(
312	            Events.SessionTitleUpdated,
313	            { sessionId, title: generatedTitle, source: "llm" },
314	            ctx.webviewId,
315	          );
316	        }
317	      }).catch((err) => {
318	        console.error("[chat.handler] Title generation failed:", err);
319	      });
320	    }
321	
322	    return { done: true };
323	  } catch (err) {
324	    ctx.setTurn(null);
325	
326	    const code = getErrorCode(err);
327	    const phase = classifyError(code);
328	    // 优先使用完整的原始 JSON 响应
329	    const detail = err instanceof CliError && err.rawResponse ? err.rawResponse : err instanceof Error ? err.message : String(err);
330	    const message = getUserMessage(code, err instanceof Error ? err.message : String(err));
331	
332	    ctx.broadcast(
333	      Events.StreamEvent,
334	      {
335	        type: "error",
336	        code,
337	        message,
338	        detail,
339	        phase,
340	        _sessionId: sessionId,
341	        mode,
342	      },
343	      ctx.webviewId,
344	    );
345	
346	    return { done: false };
347	  }
348	};
