350	const abortChat: Handler<void, { aborted: boolean }> = async (_, ctx) => {
351	  const turn = ctx.getTurn();
352	  const sessionId = ctx.getSession()?.sessionId ?? ctx.fileManager.getSessionId(ctx.getFileManagerKey());
353	
354	  // 1. Broadcast stream_aborted IMMEDIATELY so the webview UI resets
355	  //    without waiting for the CLI to acknowledge cancellation.
356	  //    The real terminal event (stream_complete or error) may still arrive
357	  //    from the CLI; the webview must handle both gracefully.
358	  if (sessionId) {
359	    handlerLog.warn("Emitting stream_aborted", { sessionId });
360	    ctx.broadcast(
361	      Events.StreamEvent,
362	      { type: "stream_aborted", result: { status: "interrupted" }, _sessionId: sessionId },
363	      ctx.webviewId,
364	    );
365	  }
366	
367	  // 2. Interrupt the turn asynchronously — don't block the handler on this.
368	  if (turn) {
369	    turn.interrupt().catch(() => {});
370	    ctx.setTurn(null);
371	  }
372	
373	  return { aborted: true };
374	};
