231	  [Methods.BrowseWorkDir]: async (_, ctx) => {
232	    if (!ctx.workspaceRoot) {
233	      return { ok: false, workDir: null };
234	    }
235	    const workspaceUri = vscode.Uri.file(ctx.workspaceRoot);
236	    let subdirs: string[] = [];
237	    try {
238	      const entries = await vscode.workspace.fs.readDirectory(workspaceUri);
239	      subdirs = entries
240	        .filter(([, type]) => type === vscode.FileType.Directory)
241	        .map(([name]) => name)
242	        .filter((name) => !name.startsWith("."))
243	        .sort();
244	    } catch {
245	      // Ignore errors
246	    }
247	
248	    const items: vscode.QuickPickItem[] = [
249	      { label: "$(folder) Browse...", description: "Open folder picker", alwaysShow: true },
250	      { label: "", kind: vscode.QuickPickItemKind.Separator },
251	      ...subdirs.map((name) => ({
252	        label: `$(folder) ${name}`,
253	        description: path.join(ctx.workspaceRoot!, name),
254	      })),
255	    ];
256	
257	    const picked = await vscode.window.showQuickPick(items, {
258	      placeHolder: "Select a subdirectory or browse...",
259	      title: "Working Directory",
260	    });
261	
262	    if (!picked) {
263	      return { ok: false, workDir: null };
264	    }
265	
266	    let selected: string;
267	    if (picked.label === "$(folder) Browse...") {
268	      const result = await vscode.window.showOpenDialog({
269	        canSelectFiles: false,
270	        canSelectFolders: true,
271	        canSelectMany: false,
272	        defaultUri: workspaceUri,
273	        openLabel: "Select Working Directory",
274	      });
275	      if (!result || result.length === 0) {
276	        return { ok: false, workDir: null };
277	      }
278	      selected = result[0].fsPath;
279	    } else {
280	      selected = picked.description!;
281	    }
282	
283	    if (selected !== ctx.workspaceRoot && !selected.startsWith(ctx.workspaceRoot + path.sep)) {
284	      vscode.window.showWarningMessage("Selected directory must be within the workspace.");
285	      return { ok: false, workDir: null };
286	    }
287	
288	    ctx.setCustomWorkDir(selected === ctx.workspaceRoot ? null : selected);
289	    return { ok: true, workDir: selected };
