292	  [Methods.LoadConsiliumSessionHistory]: async (params: LoadHistoryParams, ctx): Promise<StreamEvent[]> => {
293	    if (!UUID_REGEX.test(params.consiliumSessionId)) {
294	      return [];
295	    }
296	
297	    // Resolve the Think session file: check workspace-local paths first, then
298	    // fall back to legacy global path (for pre-Phase 09 sessions).
299	    let thinkFile: string | null = null;
300	    let isThinkFile = false;
301	
302	    // 1. Search workspace-local paths
303	    const candidateDirs = new Set<string>();
304	    if (params.workDir) candidateDirs.add(params.workDir);
305	    if (ctx.workDir) candidateDirs.add(ctx.workDir);
306	    if (ctx.workspaceRoot) {
307	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
308	        candidateDirs.add(dir);
309	      }
310	    }
311	    for (const dir of candidateDirs) {
312	      const wsFile = path.join(getWorkspaceThinkDir(dir), `${params.consiliumSessionId}.jsonl`);
313	      if (fs.existsSync(wsFile)) {
314	        thinkFile = wsFile;
315	        isThinkFile = true;
316	        break;
317	      }
318	    }
319	
320	    // 2. Fall back to legacy global path (pre-Phase 09 sessions)
321	    if (!isThinkFile) {
322	      const legacyFile = path.join(getThinkDir(), `${params.consiliumSessionId}.jsonl`);
323	      if (fs.existsSync(legacyFile)) {
324	        thinkFile = legacyFile;
325	        isThinkFile = true;
326	      }
327	    }
328	
329	    // Think sessions can be loaded without a workspace; Do sessions require one.
330	    if (!isThinkFile && !ctx.workDir) {
331	      return [];
332	    }
333	
334	    const fileKey = ctx.getFileManagerKey();
335	    ctx.fileManager.setSessionId(fileKey, params.consiliumSessionId);
336	    if (ctx.workDir) {
337	      BaselineManager.initSession(ctx.workDir, params.consiliumSessionId);
338	    }
339	
340	    // ---- Think session path (base history) ----
341	    const thinkEvents: StreamEvent[] = [];
342	    if (isThinkFile && thinkFile) {
343	      const lines = (await fs.promises.readFile(thinkFile, "utf-8"))
344	        .split("\n")
345	        .filter((l) => l.trim());
346	      for (const line of lines) {
347	        try {
348	          const entry = JSON.parse(line);
349	          if (entry.role === "user" || entry.role === "assistant") {
350	            thinkEvents.push({
351	              type: "Message",
352	              payload: { role: entry.role, content: entry.content },
353	              _sessionId: params.consiliumSessionId,
354	              mode: 'think',
355	            } as any);
356	          }
357	        } catch {
358	          // ignore malformed lines
359	        }
360	      }
361	    }
362	
363	    const meta = ctx.getSessionMetadata(params.consiliumSessionId);
364	    // If a think file exists and the stored mode is not explicitly 'do', treat it as a Think session.
365	    // This protects against lost globalState after extension reinstall.
366	    const mode = meta?.mode || (isThinkFile ? 'think' : 'legacy');
367	    const resolvedMode: 'think' | 'do' = mode === 'do' ? 'do' : 'think';
368	
369	    if (resolvedMode === 'think') {
370	      // Force terminal event so Think tab doesn't get stuck
371	      thinkEvents.push({
372	        type: "history_restored",
373	        result: { status: "restored" },
374	        _sessionId: params.consiliumSessionId,
375	        mode: 'think',
376	      } as any);
377	      return thinkEvents;
378	    }
379	
380	    // ---- Regular Do session path ----
381	    // Prefer the workDir supplied by the caller; fall back to registered
382	    // variants to handle Windows case-sensitivity differences.
383	    let doEvents: StreamEvent[] = [];
384	    const candidateWorkDirs = new Set<string>();
385	    if (params.workDir) candidateWorkDirs.add(params.workDir);
386	    if (ctx.workDir) candidateWorkDirs.add(ctx.workDir);
387	    if (ctx.workspaceRoot) {
388	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
389	        candidateWorkDirs.add(dir);
390	      }
391	    }
392	    if (candidateWorkDirs.size === 0) {
393	      return [];
394	    }
395	    for (const dir of candidateWorkDirs) {
396	      try {
397	        const events = await parseSessionEvents(dir, params.consiliumSessionId);
398	        if (events.length > 0) {
399	          doEvents = events;
400	          break;
401	        }
402	      } catch {
403	        // try next candidate
404	      }
405	    }
406	
407	    const events = [
408	      ...thinkEvents,
409	      ...doEvents.map((e) => ({ ...e, _sessionId: params.consiliumSessionId, mode: 'do' as const }) as any),
410	    ];
411	
412	    // If the previous CLI process was killed (window reload), wire.jsonl ends
413	    // mid-stream. The webview would stay stuck in isProcessing=true.
414	    // Append a history_restored event to unlock the UI.
415	    if (!ctx.getTurn()) {
416	      const last = events[events.length - 1] as any;
417	      const isTerminal =
418	        last &&
419	        (last.type === "stream_complete" ||
420	          last.type === "stream_aborted" ||
421	          last.type === "history_restored" ||
422	          last.type === "error" ||
423	          last.type === "turn_complete" ||
424	          last.type === "done");
425	      if (!isTerminal) {
426	        events.push({
427	          type: "history_restored",
428	          result: { status: "restored" },
429	          _sessionId: params.consiliumSessionId,
430	          mode: 'do',
431	        } as any);
432	      }
433	    }
434	
435	    return events;
436	  },
